package net.officefloor.hq.app.rollup;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Records, after the change's own lines, the figures it moved: a ROLLUP line per person whose
 * claimed, due-total or overdue-total changed, then a TOTALS line when the sheet's totals changed. The sheet's
 * today is read again, as the change may have moved it.
 */
public class AuditRollup {
    public void audit(@Val Sheet sheet, @Val Rollup before, SheetRepository sheets, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SettingsRepository settings, HttpServletRequest request, Audit audit) {
        Rollup after = Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates,
                settings.find(sheet.id()));
        after.changesSince(before, sheet.id(), Audit.user(request)).forEach(audit::record);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Keeps the sheet's figures before the change, so {@link AuditRollup} can tell which moved. */
public class TakeRollup {
    public void take(@Val Sheet sheet, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SettingsRepository settings,
            Out<Rollup> rollupOut) {
        rollupOut.set(Rollup.of(sheet.id(), sheet.today(), people, claims, rates,
                settings.find(sheet.id())));
    }
}
# Change the sheet's today. Validate first so a bad date is a 400, not masked by a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: score
# While the score log is on: each person's score on the day being left, before the snapshot lines.
score:
  class: net.officefloor.hq.app.rollup.AuditScore
  govern: [ transaction ]
  next: snapshot
# Each person's due-total on the day being left, before any period closes.
snapshot:
  class: net.officefloor.hq.app.rollup.AuditSnapshot
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveToday
  govern: [ transaction ]
  next: autoClose
# Once the new today is set: every open period past its to-date plus the grace days closes.
autoClose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithToday
  govern: [ transaction ]

